// Build Basic Auth header from env vars
const key = $env.MPESA_CONSUMER_KEY;
const secret = $env.MPESA_CONSUMER_SECRET;
const base = $env.MPESA_BASE_URL || 'https://sandbox.safaricom.co.ke';

if (!key || !secret) {
  throw new Error('MPESA_CONSUMER_KEY / MPESA_CONSUMER_SECRET not set in env');
}

const token = Buffer.from(`${key}:${secret}`).toString('base64');

return [{ json: { authHeader: `Basic ${token}`, baseUrl: base } }];

// Return token + computed expiry
const token = $json.access_token;
const expiresIn = parseInt($json.expires_in || '3599', 10);

if (!token) {
  throw new Error('No access_token in Daraja response: ' + JSON.stringify($json));
}

return [{
  json: {
    access_token: token,
    expires_in: expiresIn,
    expires_at: new Date(Date.now() + expiresIn * 1000).toISOString()
  }
}];
